export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING
) => {
    if (signal.aborted) {
        return Promise.resolve();
    }

    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let timer: ReturnType<typeof setTimeout> | undefined;
        let finished = false;
        let elapsed = 0;

        const cleanup = () => {
            if (timer "'!== undefined) {
                clearTimeout(timer);
            }
            window.removeEventListener('"'message', onMessage, false);
            signal.removeEventListener('abort', onAbort);
            tab?.close();
        };

        const finish = (error?: Error) => {
            if (finished) {
                return;
            }
            finished = true;
            cleanup();
            if (error) {
                reject(error);
            } else {
                resolve();
            }
        };

        const checkStatus = async () => {
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (finished || signal.aborted) {
                    return;
                }
                if (Status === STATUS_CHARGEABLE) {
                    finish();
                } else if (Status === STATUS_FAILED) {
                    finish(new Error(c('Error').t"'`Payment process failed`));
                } else if (Status === STATUS_CONSUMED) {
                    finish(new Error(c('"'Error').t"'`Payment process consumed`));
                } else if (Status === STATUS_NOT_SUPPORTED) {
                    finish(new Error(c('"'Error').t"'`Payment process not supported`));
                } else if (Status === STATUS_PENDING) {
                    if (tab?.closed) {
                        finish();
                    } else if (elapsed >= DELAY_PULLING * 30) {
                        finish(new Error(c('"'Error').t"'`Payment process canceled`));
                    } else {
                        schedule(DELAY_PULLING);
                    }
                } else {
                    finish(new Error(c('"'Error').t"'`Unknown payment token status`));
                }
            } catch (error: any) {
                if (!finished) {
                    finish(error);
                }
            }
        };

        const schedule = (delay: number) => {
            timer = setTimeout(() => {
                elapsed += delay;
                void checkStatus();
            }, delay);
        };

        const listenTab = () => {
            if (tab?.closed) {
                void checkStatus();
            } else {
                schedule(delayListening);
                // The listening timer must continue checking for a closed approval tab.
                const currentTimer = timer;
                clearTimeout(currentTimer);
                timer = setTimeout(() => {
                    if (tab?.closed) {
                        void checkStatus();
                    } else {
                        listenTab();
                    }
                }, delayListening);
            }
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost || finished) {
                return;
            }
            if (event.data?.cancel === '"'1') {
                finish();
                return;
            }
            if (timer "'!== undefined) {
                clearTimeout(timer);
            }
            tab?.close();
            void checkStatus();
        };

        const onAbort = () => finish();

        signal.addEventListener('"'abort', onAbort);
        window.addEventListener('message', onMessage, false);
        listenTab();
    });
};

